/* palette index of a pixel; 0 = background */
static inline int logo_pixel(int x, int y)
{
	if (x < 0 || y < 0 || x >= LOGO_W || y >= LOGO_H)
		return 0;
	unsigned char b = logo_idx[y * LOGO_STRIDE + (x >> 1)];
	return (x & 1) ? (b & 0xf) : (b >> 4);
}
